CREATE COLUMN TABLE "TEST_AP"."RPRS" ("SeqID" INTEGER CS_INT NOT NULL , "SeqName" NVARCHAR(254), "LineNum" SMALLINT CS_INT, "ObjectID" INTEGER CS_INT, "SubDocType" SMALLINT CS_INT, PRIMARY KEY ("SeqID")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE INDEX "RPRS_OBJECT_ID" ON "TEST_AP"."RPRS" ( "ObjectID" ASC )